package com.creatio.autotest.testdata.models;

/**
 * Маршрут рассмотрения заявки. Определяется продуктом (не вычисляется из суммы).
 * Источник правды после скоринга — деталь "Утверждённые параметры → Маршрут рассмотрения".
 */
public enum CreditRoute {

    /**
     * Упрощённый (500–30000): скоринг обязан вернуть "Одобрить",
     * заявка авто-уходит на "Информирование клиента".
     * Верификатор и кредитный комитет НЕ участвуют.
     */
    SIMPLIFIED("Упрощенный"),

    /**
     * Стандартный (30001–100000): любое из 4 решений скоринга,
     * заявка ВСЕГДА идёт через верификатора и кредитный комитет.
     */
    STANDARD("Стандартный");

    private final String uiText;

    CreditRoute(String uiText) {
        this.uiText = uiText;
    }

    /** Текст маршрута как он отображается в UI (для assert против "Утверждённых параметров"). */
    public String getUiText() {
        return uiText;
    }
}